  let org = orgBySlug(record.organization.slug) || orgById(record.organization.id);
  if (!org) { org = { id: record.organization.id || uid('org'), name: record.organization.name, slug: record.organization.slug, category: record.organization.category || 'Service organization', contact: record.organization.contact || '', users: [], services: [], createdAt: new Date().toISOString() }; state.organizations.push(org); }
