function publicTop(org) { return `<div class="public-top"><a class="brand" href="#/"><span class="brand-mark">${icon('queue', 18)}</span><span>QueueHub <small style="font-size:10px;color:var(--aqua-dark);font-weight:800;letter-spacing:.02em">LineLess</small></span></a><div class="org-crumb"><span class="org-avatar">${initials(org.name)}</span><span>${esc(org.name)}</span><span class="badge badge-gray">Customer view</span></div></div>`; }
