  if (type === 'service') { const org = authOrg(); const id=form.dataset.serviceId; const existing=serviceById(org,id); const scheduleType=data.get('scheduleType'); const selectedDays=[...form.querySelectorAll('input[name="day"]:checked')].map(x=>Number(x.value)); const selectedDates=String(data.get('serviceDates') || todayISO()).split(',').map(value=>value.trim()).filter(value=>/^\d{4}-\d{2}-\d{2}$/.test(value)); const publishField=form.querySelector('input[name="publish"]'); const published=existing ? publishField?.checked === true : (publishField ? publishField.checked : true); const service={ id:existing?.id||uid('svc'), slug:existing?.slug||slugify(data.get('name')), name:data.get('name').trim(), description:data.get('description').trim(), category:data.get('category'), prefix:(data.get('prefix').trim().toUpperCase()||data.get('name').trim().slice(0,1).toUpperCase()), published, schedule:{ type:scheduleType || 'specific', dates:scheduleType==='specific'?(selectedDates.length?selectedDates:[todayISO()]):(existing?.schedule?.dates||[]), days:scheduleType==='recurring'?(selectedDays.length?selectedDays:[0,1,2,3,4,5]):(existing?.schedule?.days||[]), openingTime:data.get('openingTime') || '00:00', startTime:data.get('startTime') || '00:00', closingTime:data.get('closingTime') || '23:59', cutoffTime:data.get('cutoffTime') || '23:59', maxTokens:Number(data.get('maxTokens')) || 150, counters:Number(data.get('counters')) || 1, avgMinutes:Number(data.get('avgMinutes')) || 5, graceSeconds:Math.max(30, Number(data.get('graceSeconds')) || 120), notifications:data.get('notifications')!=='false' }, queueGeneration:existing?.queueGeneration || 1, tokens:existing?.tokens||[], paused:existing?.paused||false, createdAt:existing?.createdAt||new Date().toISOString() }; if(existing && !window.confirm('Update Service?\n\nUpdating this service will start a fresh queue. Existing customers will no longer appear in the active queue.')) return; if(existing) { const idx=org.services.findIndex(s=>s.id===existing.id); org.services[idx]=service; } else org.services.push(service); saveState(); const synced=await syncServiceToBackend(org, service, { refreshQueue:Boolean(existing) }); if(synced?.service) mergeSharedRecord(synced); closeModal(); ui.adminTab='services'; ui.shareServiceId=service.published ? service.id : null; render(); if(synced?.__error) showToast(synced.error || 'Service was saved locally, but the shared queue could not be refreshed.', 'error'); else showToast(existing ? 'Service updated and queue refreshed.' : (service.published ? 'Service created and published.' : 'Service saved as a draft.')); if(service.published) setTimeout(() => openModal(shareModal(org, service)), 80); return; }
  if (type === 'reset-staff') { const org=authOrg(); const staff=org?.users.find(user=>user.id===form.dataset.userId); const password=String(data.get('password')||''); if(!staff||password.length<6) return showToast('Password must be at least 6 characters.', 'error'); staff.password=password; saveState(); await syncOrganizationToBackend(org); closeModal(); render(); showToast('Staff password updated successfully.'); return; }
